<?phprequire_once('common_api_header.php');require_once('../admin/controllers/common_controllers.php');require_once('../admin/employees/controller/employee_controller.php');require_once('../admin/authentication/auth_controller/authentication_controller.php');$data_raw = file_get_contents('php://input');$data = json_decode($data_raw,true);$response = array();if(isset($data['username']) && isset($data['password'])){	$conn = _connectodb();	$response = _api_login_user($conn,$data);}else{	$response["error"] = true;	$response["message"] = "Missing User Fields";}echo json_encode($response);?>